mapper.select:
SELECT * FROM knowledge_handbook


        AND category = #{category}


        AND project = #{project}


        AND (
            title LIKE CONCAT('%', #{q}, '%')
            OR symptom LIKE CONCAT('%', #{q}, '%')
            OR cause LIKE CONCAT('%', #{q}, '%')
            OR fix LIKE CONCAT('%', #{q}, '%')
            OR IFNULL(tags, '') LIKE CONCAT('%', #{q}, '%')
        )


ORDER BY updated_at DESC, id DESC
LIMIT #{limit}
